import{c as e,a6 as r,x as t,A as l,f as s,i,l as o}from"./chunks/framework.D70RugSU.js";const b=JSON.parse('{"title":"北海道旅2","description":"","frontmatter":{"title":"北海道旅2","date":"2026-04-27T00:00:00.000Z","outline":[2,3],"lastUpdated":true,"sidebar":false,"tags":["旅","北海道"]},"headers":[],"relativePath":"posts/hrd-travel_02.md","filePath":"posts/hrd-travel_02.md","lastUpdated":1780068535000}'),d={name:"posts/hrd-travel_02.md"};function n(p,a,h,_,c,m){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="🎥-北海道一周の旅-day-2" tabindex="-1">🎥 北海道一周の旅｜Day 2 <a class="header-anchor" href="#🎥-北海道一周の旅-day-2" aria-label="Permalink to “🎥 北海道一周の旅｜Day 2”">​</a></h1><h2 id="_4月27日-新潟港-〜-北海道へ-小樽港" tabindex="-1">4月27日 新潟港 〜 北海道へ（小樽港） <a class="header-anchor" href="#_4月27日-新潟港-〜-北海道へ-小樽港" aria-label="Permalink to “4月27日 新潟港 〜 北海道へ（小樽港）”">​</a></h2><h1 id="旅途记录-4-27-4-28-旅の記録-4-27-4-28" tabindex="-1">旅途记录 4.27～4.28 / 旅の記録 4.27～4.28 <a class="header-anchor" href="#旅途记录-4-27-4-28-旅の記録-4-27-4-28" aria-label="Permalink to “旅途记录 4.27～4.28 / 旅の記録 4.27～4.28”">​</a></h1><h2 id="_4月27日-·-出发-出発" tabindex="-1">4月27日 · 出发 / 出発 <a class="header-anchor" href="#_4月27日-·-出发-出発" aria-label="Permalink to “4月27日 · 出发 / 出発”">​</a></h2><p>中午左右，坐上了从新潟出发的船。 新潟大概有70万人口，跟浜松差不多大的城市。没想到早上路上的车还挺多的。</p><p>昼ごろ、新潟からフェリーに乗った。 新潟は人口70万くらいで、浜松とだいたい同じくらいの規模の街だ。朝の道路が思ったより混んでいて、ちょっと意外だった。</p><p><img src="'+s+'" alt="&quot;新日本海フェリー&quot;" loading="lazy"></p><h2 id="出发前-乗る前に" tabindex="-1">出发前 / 乗る前に <a class="header-anchor" href="#出发前-乗る前に" aria-label="Permalink to “出发前 / 乗る前に”">​</a></h2><p>去港口之前，顺路去了一趟 <strong>マックスバリュ</strong>。 想着船上的午饭和晚饭，买了一堆零食、泡面还有惣菜。东西买了不少。</p><p>港に行く前に、<strong>マックスバリュ</strong>に寄った。 船の中でのお昼とか夕ご飯のことを考えて、お菓子やカップ麺、惣菜をいろいろ買い込んだ。けっこうな量になった。</p><p><img src="'+i+'" alt="&quot;カレーヌードル&quot;" loading="lazy"></p><h2 id="船上-船の中で" tabindex="-1">船上 / 船の中で <a class="header-anchor" href="#船上-船の中で" aria-label="Permalink to “船上 / 船の中で”">​</a></h2><p>刚上船的时候还挺兴奋的，到处转了好几圈。 但过了一会儿，新鲜感一过，就开始觉得好无聊了。</p><p>乗ったばかりのころはテンションが上がって、船の中をぐるぐる歩き回った。 でも少し経つと新鮮さも薄れて、だんだん暇になってきた。</p><p><img src="'+o+'" alt="&quot;船で撮った写真&quot;" loading="lazy"></p><h2 id="夜-夜" tabindex="-1">夜 / 夜 <a class="header-anchor" href="#夜-夜" aria-label="Permalink to “夜 / 夜”">​</a></h2><p>晚上10点多，船舱的灯关了。 躺下来之后也没睡太好——跟3年前从九州去大阪的那次比起来，感觉睡得差多了。</p><p>夜10時すぎに電気が消えた。 横になったけど、あんまりよく眠れなかった。3年前に九州から大阪に行ったときと比べると、全然眠れた感じがしない。</p><p>可能还是太兴奋了，睡不着。</p><p>たぶん、テンションが上がりすぎてたんだと思う。</p>',20)])])}const u=e(d,[["render",n]]);export{b as __pageData,u as default};
